import React from 'react';
import styled from 'styled-components';
import { useHistory } from 'react-router-dom';

function Login({ onLogin }) {
  const history = useHistory();

  const handleLogin = () => {
    onLogin();
    history.push('/home');
  };

  return (
    <>
      <Container>
        <CTA>
          <CTALogoOne src="/images/cta-logo-one.svg" />
          <FormContainer>
            <EmailInput type="email" placeholder="Email" />
            <SignUp onClick={handleLogin}>SIGN UP NOW</SignUp>
          </FormContainer>
          <Description>
            Stream brand new Originals, blockbusters, binge-worthy series, and more.
            All at no extra cost. Cancel at any time.*
            Enter your email to create or restart your subscription.
          </Description>
          <CTALogoTwo src="/images/cta-logo-two.png" />
        </CTA>
      </Container>
      <HeroSection>
     
        <LeftColumn>
          <Heading>Only on Disney+</Heading>
          <Subheading>
            Exclusive series and Originals you won't find on any other streaming service.
          </Subheading>
          <Copyright>© 2023 TAS Rights Management LLC</Copyright>
        </LeftColumn>
        <RightColumn>
        <HeroImage src="/images/shogun.jpg" alt="Shogun Banner" />
        </RightColumn>
      </HeroSection>
    </>
  );
}

export default Login;


